1	/* One floating island nav for every page. site-nav.js builds the markup.
2	   Light pill on light pages. Over an element marked data-nav="dark" it turns into a dark pill. */
3	:root{--sn-ink:oklch(22% .012 255);--sn-mut:oklch(48% .013 255);--sn-line:oklch(91.6% .007 255);--sn-panel:oklch(99.7% .0015 255);--sn-hover:oklch(96.2% .007 255);
4	--sn-test:oklch(55% .19 256);--sn-test-d:oklch(47% .17 256);--sn-test-bg:oklch(95.6% .026 256);--sn-audit:oklch(52% .2 295);--sn-audit-d:oklch(45% .18 295);--sn-audit-bg:oklch(95.8% .03 295);--sn-ok:oklch(52% .14 150);
5	--sn-sh:0 1px 2px oklch(30% .02 255/.06),0 10px 30px -12px oklch(30% .04 255/.24);--sn-ease:cubic-bezier(.22,1,.36,1)}
6	html{scroll-padding-top:88px}
7	#sitenav{height:76px}
8	.sn-nav{position:fixed;top:12px;left:50%;transform:translateX(-50%);z-index:60;width:max-content;max-width:calc(100% - 24px);font-family:Geist,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;color:var(--sn-ink)}
9	.sn-bar{--bi:var(--sn-ink);--bm:var(--sn-mut);--bh:var(--sn-hover);display:flex;align-items:center;gap:2px;height:54px;padding:0 7px 0 14px;border-radius:99px;background:var(--sn-panel);border:1px solid var(--sn-line);box-shadow:var(--sn-sh);
10	 transition:background-color .35s var(--sn-ease),border-color .35s var(--sn-ease),box-shadow .35s var(--sn-ease)}
11	.sn-nav a{text-decoration:none;color:inherit}
12	.sn-wm{display:inline-flex;align-items:center;gap:8px;font-weight:700;font-size:15.5px;letter-spacing:-.025em;margin-right:8px;color:var(--bi)!important;border-radius:99px}
13	.sn-wm svg{width:26px;height:26px;display:block;flex:none}
14	.sn-apps,.sn-links{display:flex;align-items:center;gap:2px}
15	.sn-sep{width:1px;height:22px;background:var(--sn-line);margin:0 8px;transition:background-color .35s}
16	.sn-sp{flex:1;min-width:8px}
17	.sn-app,.sn-lk{position:relative;display:inline-flex;align-items:center;gap:8px;height:38px;min-height:0;padding:0 12px 0 6px;border:0;background:none;border-radius:99px;font-family:inherit;font-size:14px;font-weight:500;line-height:1;color:var(--bi);cursor:pointer;white-space:nowrap;transition:background-color .2s,color .2s}
18	.sn-nav .sn-lk{padding:0 11px;color:var(--bm);font-size:14px}
19	.sn-app:hover,.sn-lk:hover,.sn-app[aria-expanded=true]{background:var(--bh)}
20	.sn-nav .sn-lk:hover,.sn-nav .sn-lk.is-here{color:var(--bi)}
21	.sn-app b{font-weight:650;letter-spacing:-.01em}
22	/* where you are: the current page gets a tinted pill and a colored underline. On the home page the section you are reading gets the underline. */
23	.sn-app[aria-current=page].a-test{background:var(--sn-test-bg);color:var(--sn-test-d)}
24	.sn-app[aria-current=page].a-audit{background:var(--sn-audit-bg);color:var(--sn-audit-d)}
25	.sn-nav .sn-lk[aria-current=page]{color:var(--bi);background:var(--bh);font-weight:600}
26	.sn-app[aria-current=page]:after,.sn-lk[aria-current=page]:after,.sn-app.is-here:after,.sn-lk.is-here:after{content:"";position:absolute;left:50%;bottom:3px;width:18px;height:2.5px;margin-left:-9px;border-radius:2px;background:var(--sn-test)}
27	.sn-app.a-audit[aria-current=page]:after,.sn-app.a-audit.is-here:after{background:var(--sn-audit)}
28	.sn-app[aria-current=page]:after{left:calc(50% + 17px)}.sn-app.is-here:after{left:calc(50% + 17px)}
29	.sn-lk.is-here{color:var(--bi)}
30	.sn-tile{display:inline-grid;place-items:center;width:28px;height:28px;border-radius:8px;color:oklch(99.5% .003 256);flex:none}
31	.sn-tile svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
32	.t-test{background:var(--sn-test)}.t-audit{background:var(--sn-audit)}
33	.sn-car{width:12px;height:12px;fill:none;stroke:var(--bm);stroke-width:1.8;transition:transform .25s var(--sn-ease)}
34	.sn-app[aria-expanded=true] .sn-car{transform:rotate(180deg)}
35	.sn-gh{display:inline-grid;place-items:center;width:38px;height:38px;border-radius:99px;color:var(--bm)!important;transition:background-color .2s,color .2s}
36	.sn-gh:hover{background:var(--bh);color:var(--bi)!important}
37	.sn-gh svg{width:17px;height:17px;fill:currentColor}
38	/* the one primary action */
39	.sn-try{display:inline-flex;align-items:center;height:38px;padding:0 17px;margin-left:4px;border-radius:99px;background:var(--sn-test);color:oklch(99.5% .003 256)!important;font-weight:600;font-size:14px;letter-spacing:-.01em;white-space:nowrap;box-shadow:0 1px 0 oklch(100% 0 0/.18) inset,0 6px 16px -8px oklch(55% .19 256/.8);transition:background-color .2s}
40	.sn-try:hover{background:var(--sn-test-d)}
41	.sn-burger{display:none;width:40px;height:40px;margin-left:4px;padding:0;min-height:0;border:0;border-radius:99px;background:none;cursor:pointer;color:var(--bi);place-items:center}
42	.sn-burger:hover{background:var(--bh)}
