html.ar-lock.ar-gut{scrollbar-gutter:stable}
.ar-dlg{--ar-acc:var(--sn-test);--ar-acc-d:var(--sn-test-d);--ar-acc-bg:var(--sn-test-bg);--ar-code:oklch(97.3% .004 255);--ar-ease:cubic-bezier(.22,1,.36,1);
 position:fixed;inset:0;margin:auto;width:min(880px,calc(100vw - 32px));max-width:none;height:fit-content;max-height:min(900px,calc(100dvh - 48px));
 padding:0;border:0;border-radius:20px;background:var(--sn-panel);color:var(--sn-ink);overflow:hidden;
 box-shadow:0 1px 2px oklch(30% .02 255/.08),0 24px 70px -20px oklch(25% .05 265/.45);
 font-family:Geist,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;font-size:15px;line-height:1.5;text-align:left;-webkit-font-smoothing:antialiased}
