@keyframes ar-fade{from{opacity:0}}
.ar-dlg[data-task=audit]{--ar-acc:var(--sn-audit);--ar-acc-d:var(--sn-audit-d);--ar-acc-bg:var(--sn-audit-bg)}
.ar-dlg[data-task=receipt]{--ar-acc:var(--sn-ink);--ar-acc-d:var(--sn-ink);--ar-acc-bg:oklch(96.6% .006 255)}
.ar-dlg *{box-sizing:border-box}
.ar-dlg :where(h2,h3,p,ol,ul,li,pre,figure,fieldset,legend,details,summary){margin:0;padding:0}
.ar-dlg :where(button){font:inherit;color:inherit;min-height:0;letter-spacing:normal;text-transform:none;box-shadow:none}
.ar-dlg a{color:inherit;text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:3px}
.ar-dlg code,.ar-dlg pre,.ar-mono{font-family:"Geist Mono",ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
.ar-dlg :focus-visible{outline:3px solid var(--sn-test);outline-offset:2px}
.ar-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}

/* header: title, one line, the two tabs. It stays put while the body scrolls. */
.ar-head{flex:none;padding:24px 28px 0;border-bottom:1px solid var(--sn-line)}
.ar-top{display:flex;align-items:flex-start;gap:14px}
.ar-mark{display:inline-grid;place-items:center;width:40px;height:40px;border-radius:11px;background:var(--sn-ink);color:oklch(98% .004 255);flex:none}
.ar-mark svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.ar-mark .sn-spark{fill:oklch(80% .12 295);stroke:none}
.ar-title{flex:1;min-width:0}
.ar-dlg h2{font-size:22px;line-height:1.2;font-weight:700;letter-spacing:-.025em}
.ar-sub{margin-top:3px;color:var(--sn-mut);font-size:15px}
.ar-x{display:inline-grid;place-items:center;width:38px;height:38px;flex:none;margin:-4px -8px 0 0;border:0;border-radius:99px;background:none;color:var(--sn-mut);cursor:pointer;transition:background-color .2s,color .2s}
.ar-x:hover{background:var(--sn-hover);color:var(--sn-ink)}
.ar-x svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round}
.ar-tabs{display:flex;gap:4px;margin-top:16px}
.ar-tab{position:relative;height:42px;padding:0 12px;border:0;background:none;cursor:pointer;font-size:14.5px;font-weight:600;color:var(--sn-mut);border-radius:10px 10px 0 0;transition:color .2s}
.ar-tab:hover{color:var(--sn-ink)}
.ar-tab[aria-selected=true]{color:var(--sn-ink)}
.ar-tab[aria-selected=true]:after{content:"";position:absolute;left:12px;right:12px;bottom:-1px;height:2.5px;border-radius:2px;background:var(--sn-ink)}
.ar-tab .ar-mono{font-weight:500;font-size:13.5px}

/* body: the only part that scrolls */
.ar-body{flex:1 1 auto;min-height:0;overflow:auto;overscroll-behavior:contain;padding:22px 28px 26px}
.ar-panel[hidden]{display:none}

/* a. the one prompt, and the task that fills its second line */
.ar-seg{display:inline-grid;grid-template-columns:repeat(3,auto);gap:2px;padding:3px;border:0;border-radius:12px;background:oklch(95.6% .006 255);min-inline-size:0}
.ar-seg input{position:absolute;opacity:0;width:1px;height:1px;pointer-events:none}
.ar-seg label{display:flex;align-items:center;justify-content:center;gap:7px;min-height:36px;padding:6px 14px;border-radius:9px;font-size:14px;font-weight:550;color:var(--sn-mut);cursor:pointer;text-align:center;line-height:1.2;transition:background-color .2s,color .2s,box-shadow .2s}
.ar-seg label:hover{color:var(--sn-ink)}
.ar-seg input:checked+label{background:var(--sn-panel);color:var(--sn-ink);box-shadow:0 1px 2px oklch(30% .02 255/.1),0 2px 8px -4px oklch(30% .02 255/.18)}
.ar-seg input:focus-visible+label{outline:3px solid var(--sn-test);outline-offset:1px}
.ar-dot{width:8px;height:8px;border-radius:50%;flex:none}
.ar-dot.d-test{background:var(--sn-test)}.ar-dot.d-audit{background:var(--sn-audit)}.ar-dot.d-receipt{background:var(--sn-ink)}
.ar-prompt{margin-top:12px;border-radius:16px;background:var(--ar-acc-bg);padding:20px 20px 16px;transition:background-color .25s var(--ar-ease)}
.ar-ptext{font-size:17.5px;line-height:1.55;letter-spacing:-.008em;color:var(--sn-ink);overflow-wrap:anywhere}
.ar-ptext span{display:block}
.ar-ptext .l1{font-weight:600}
.ar-ptext .l2{color:var(--ar-acc-d);margin-top:2px}
.ar-pfoot{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:16px;flex-wrap:wrap}
.ar-where{font-size:13.5px;color:var(--sn-mut)}
.ar-copy{display:inline-flex;align-items:center;gap:8px;height:42px;padding:0 18px;border:0;border-radius:99px;background:var(--ar-acc);color:oklch(99% .003 256);font-size:15px;font-weight:600;cursor:pointer;white-space:nowrap;transition:background-color .2s}
.ar-copy:hover{background:var(--ar-acc-d)}
.ar-dlg[data-task=receipt] .ar-copy:hover{background:oklch(32% .015 255)}
.ar-copy svg,.ar-ic svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}

/* section labels */
.ar-h{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin:28px 0 12px}
.ar-dlg h3{font-size:16px;font-weight:650;letter-spacing:-.012em}
.ar-os{display:inline-flex;gap:2px;padding:2px;border-radius:10px;background:oklch(95.6% .006 255)}
.ar-os button{height:30px;padding:0 11px;border:0;border-radius:8px;background:none;font-size:13px;font-weight:550;color:var(--sn-mut);cursor:pointer}
.ar-os button[aria-pressed=true]{background:var(--sn-panel);color:var(--sn-ink);box-shadow:0 1px 2px oklch(30% .02 255/.12)}

/* c. the steps */
.ar-steps{list-style:none;display:flex;flex-direction:column;gap:6px;counter-reset:ar}
.ar-step{display:grid;grid-template-columns:28px 1fr;gap:3px 12px;padding:12px 0 12px;border-top:1px solid var(--sn-line)}
.ar-step:first-child{border-top:0;padding-top:2px}
.ar-n{grid-row:1/span 3;display:inline-grid;place-items:center;width:26px;height:26px;border-radius:50%;background:oklch(95.6% .006 255);font-size:13px;font-weight:650;color:var(--sn-ink);font-variant-numeric:tabular-nums}
.ar-step b{font-size:15px;font-weight:600;letter-spacing:-.01em}
.ar-step p{font-size:14px;color:var(--sn-mut);line-height:1.45}
.ar-step p code,.ar-dlg li>p code{font-size:.9em;color:var(--sn-ink);background:oklch(95.6% .006 255);border-radius:5px;padding:.05em .32em;border:0}
.ar-cmd{position:relative;margin-top:7px;border-radius:12px;background:var(--ar-code);border:1px solid oklch(93% .006 255)}
.ar-cmd pre{margin:0;padding:11px 52px 11px 14px;max-height:none;font-size:13px;line-height:1.6;color:var(--sn-ink);white-space:pre;overflow-x:auto;background:none;border:0;word-break:normal;overflow-wrap:normal}
.ar-ic{position:absolute;top:6px;right:6px;display:inline-grid;place-items:center;width:34px;height:34px;border:0;border-radius:9px;background:var(--sn-panel);color:var(--sn-mut);cursor:pointer;box-shadow:0 0 0 1px oklch(91% .007 255);transition:color .2s,background-color .2s}
.ar-ic:hover{color:var(--sn-ink)}
.ar-ic.done,.ar-copy.done{color:oklch(99% .003 256);background:var(--sn-ok)}
.ar-ic.done{box-shadow:none}

/* d. the JSON, folded by default, and the safety chips */
.ar-json{margin-top:22px;border:1px solid var(--sn-line);border-radius:14px}
.ar-json>summary{display:flex;align-items:center;gap:10px;min-height:48px;padding:0 16px;cursor:pointer;list-style:none;font-size:15px;font-weight:600;border-radius:14px}
.ar-json>summary::-webkit-details-marker{display:none}
.ar-json>summary:hover{background:var(--sn-hover)}
.ar-json>summary:after{content:"";margin-left:auto;width:7px;height:7px;border-right:2px solid var(--sn-mut);border-bottom:2px solid var(--sn-mut);transform:translateY(-2px) rotate(45deg);transition:transform .2s var(--ar-ease)}
.ar-json[open]>summary:after{transform:translateY(2px) rotate(225deg)}
.ar-json>summary small{font-size:13px;font-weight:450;color:var(--sn-mut)}
.ar-jin{padding:4px 16px 16px;display:grid;gap:14px}
.ar-jin p{font-size:13.5px;color:var(--sn-mut)}
.ar-jin p code{font-size:.92em;color:var(--sn-ink)}
.ar-jin pre{margin-top:6px;padding:12px 14px;border-radius:12px;background:var(--ar-code);border:1px solid oklch(93% .006 255);font-size:12.5px;line-height:1.6;color:var(--sn-ink);white-space:pre;overflow-x:auto;max-height:none}
.ar-jin .k{color:oklch(45% .15 256)}.ar-jin .s{color:oklch(44% .12 150)}.ar-jin .v{color:oklch(48% .17 295)}
.ar-safe{display:flex;flex-wrap:wrap;gap:8px;margin-top:22px;list-style:none}
.ar-safe li{display:inline-flex;align-items:center;gap:8px;min-height:36px;padding:6px 14px 6px 10px;border-radius:99px;background:oklch(96.4% .02 150);color:oklch(30% .06 150);font-size:14px;font-weight:550}
.ar-safe svg{width:16px;height:16px;flex:none;fill:none;stroke:var(--sn-ok);stroke-width:2;stroke-linecap:round;stroke-linejoin:round}

/* e. the links */
.ar-links{display:flex;flex-wrap:wrap;gap:6px 20px;margin-top:22px;padding-top:18px;border-top:1px solid var(--sn-line);font-size:14.5px;font-weight:500}
.ar-links a{color:var(--sn-test-d)}
.ar-links a:hover{color:var(--sn-ink)}

/* f. the full agent.md */
.ar-raw-bar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:12px}
.ar-raw-bar .ar-meta{font-size:13.5px;color:var(--sn-mut);margin-right:auto}
.ar-raw-bar .ar-meta b{color:var(--sn-ink);font-weight:600}
.ar-raw-bar a{font-size:14px;font-weight:500;color:var(--sn-test-d)}
.ar-dlg[data-task] .ar-raw-bar .ar-copy{background:var(--sn-ink);height:38px;padding:0 15px;font-size:14px}
.ar-dlg[data-task] .ar-raw-bar .ar-copy:hover{background:oklch(32% .015 255)}
.ar-dlg[data-task] .ar-raw-bar .ar-copy.done{background:var(--sn-ok)}
.ar-raw{margin:0;padding:16px 18px;border-radius:14px;background:var(--ar-code);border:1px solid oklch(93% .006 255);font-size:12.8px;line-height:1.62;color:var(--sn-ink);white-space:pre-wrap;overflow-wrap:anywhere;word-break:normal;max-height:none;min-height:240px}
.ar-raw.wait{color:var(--sn-mut)}
.ar-fail{padding:18px;border-radius:14px;background:oklch(96.5% .03 60);color:oklch(32% .07 55);font-size:14.5px}

/* phones: a full-screen sheet */
@media(max-width:759px){
 .ar-dlg{width:100vw;height:100dvh;max-height:100dvh;border-radius:0}
 .ar-head{padding:16px 16px 0}
 .ar-dlg h2{font-size:20px}
 .ar-sub{font-size:14.5px}
 .ar-mark{width:36px;height:36px;border-radius:10px}
 .ar-tabs{margin-top:12px}
 .ar-body{padding:16px 16px 28px}
 .ar-seg{display:grid;width:100%;grid-template-columns:repeat(3,minmax(0,1fr))}
 .ar-seg label{padding:6px 6px;font-size:13px;flex-direction:column;gap:4px;min-height:52px}
 .ar-prompt{padding:16px 16px 14px}
 .ar-ptext{font-size:16px}
 .ar-pfoot{flex-direction:column-reverse;align-items:stretch}
 .ar-copy{justify-content:center}
 .ar-step{grid-template-columns:26px 1fr;gap:3px 10px}
}
@media(prefers-reduced-motion:reduce){
 .ar-dlg[open],.ar-dlg::backdrop{animation:none}
 .ar-dlg *{transition:none!important}
}

