const { chromium } = require("D:/Atharva/video-studio/node_modules/playwright");
const OUT = process.argv[2];
const H = "http://localhost:8791/";
const log = (...a) => console.log(...a);
(async () => {
  const b = await chromium.launch({ channel: "msedge" });
  const errs = [];
  async function page(w, h, opts = {}) {
    const ctx = await b.newContext({ viewport: { width: w, height: h || 900 }, ...opts });
    await ctx.grantPermissions(["clipboard-read", "clipboard-write"], { origin: "http://localhost:8791" });
    const p = await ctx.newPage();
    p.on("console", m => { if (m.type() === "error") errs.push(w + " " + p.url() + " " + m.text()); });
    p.on("pageerror", e => errs.push(w + " " + p.url() + " PAGEERROR " + e.message));
    return p;
  }
  // 1. nav at each width, home (dark hero) and doc-audit (light)
  for (const w of [1440, 1280, 1080, 760, 375]) {
    const p = await page(w);
    for (const [pg, name] of [["", "home"], ["doc-audit/", "audit"]]) {
      await p.goto(H + pg, { waitUntil: "load" }); await p.waitForTimeout(700);
      const r = await p.evaluate(() => {
        const bar = document.querySelector(".sn-bar").getBoundingClientRect();
        const ag = document.querySelector(".sn-agent"); const a = ag.getBoundingClientRect();
        return { bar: [Math.round(bar.left), Math.round(bar.width), Math.round(bar.height)], agVisible: getComputedStyle(ag.parentElement).display !== "none", agTop: Math.round(a.top), dark: document.querySelector(".sn-nav").classList.contains("dark"), hscroll: document.documentElement.scrollWidth > document.documentElement.clientWidth };
      });
      log("NAV", w, name, JSON.stringify(r));
      await p.screenshot({ path: `${OUT}/nav-${name}-${w}.png`, clip: { x: 0, y: 0, width: w, height: 84 } });
      if (w < 1080) {
        await p.click("#sn-b-more"); await p.waitForTimeout(350);
        await p.screenshot({ path: `${OUT}/menu-${name}-${w}.png`, clip: { x: 0, y: 0, width: w, height: Math.min(900, 760) } });
        await p.click("#sn-b-more"); await p.waitForTimeout(300);
      }
    }
    await p.context().close();
  }
  // 2. modal at 1440 and 375
  for (const [w, hgt] of [[1440, 900], [375, 812]]) {
    const p = await page(w, hgt);
    await p.goto(H + "doc-audit/", { waitUntil: "load" }); await p.waitForTimeout(500);
    const before = await p.evaluate(() => { const r = document.querySelector(".sn-bar").getBoundingClientRect(); return [r.left, r.width, document.documentElement.clientWidth]; });
    if (w < 760) { await p.click("#sn-b-more"); await p.waitForTimeout(300); await p.click(".sn-mm .sn-ag"); }
    else await p.click(".sn-agent");
    await p.waitForSelector("dialog.ar-dlg[open]"); await p.waitForTimeout(450);
    const st = await p.evaluate(() => ({ active: document.activeElement.id || document.activeElement.className, expanded: [...document.querySelectorAll(".sn-ag")].map(a => a.getAttribute("aria-expanded")), bar: (() => { const r = document.querySelector(".sn-bar").getBoundingClientRect(); return [r.left, r.width, document.documentElement.clientWidth]; })(), lock: getComputedStyle(document.documentElement).overflow, dlg: (() => { const r = document.querySelector(".ar-dlg").getBoundingClientRect(); return [Math.round(r.left), Math.round(r.top), Math.round(r.width), Math.round(r.height)]; })() }));
    log("MODAL", w, "before", JSON.stringify(before), "after", JSON.stringify(st));
    await p.screenshot({ path: `${OUT}/modal-quick-${w}.png` });
    // copy prompt
    await p.click("#ar-cp"); await p.waitForTimeout(200);
    const clip = await p.evaluate(() => navigator.clipboard.readText());
    const live = await p.textContent("#ar-live");
    log("COPY", w, JSON.stringify(clip), "live:", live);
    await p.screenshot({ path: `${OUT}/modal-copied-${w}.png` });
    // audit task + Windows shell
    await p.click("label[for=ar-k-audit]"); await p.waitForTimeout(200);
    await p.click(".ar-os button[data-os=ps]");
    await p.evaluate(() => document.querySelector(".ar-body").scrollTop = 330);
    await p.waitForTimeout(200);
    await p.screenshot({ path: `${OUT}/modal-audit-steps-${w}.png` });
    // step copy
    await p.click("[data-copy=ar-c4]"); await p.waitForTimeout(200);
    log("STEPCOPY", w, JSON.stringify(await p.evaluate(() => navigator.clipboard.readText())), await p.textContent("#ar-live"));
