const { chromium } = require("D:/Atharva/video-studio/node_modules/playwright");
const OUT = process.argv[2];
(async () => {
  const b = await chromium.launch({ channel: "msedge" });
  for (const [pg, name] of [["", "home"], ["doc-test/", "doctest"], ["doc-audit/", "docaudit"], ["plan/", "plan"], ["judges/", "judges"]]) {
    for (const [w, h] of [[1440, 900], [375, 812]]) {
      const ctx = await b.newContext({ viewport: { width: w, height: h } });
      const p = await ctx.newPage();
      await p.goto("http://localhost:8791/" + pg, { waitUntil: "load" }); await p.waitForTimeout(500);
      if (w < 1080) { await p.click("#sn-b-more"); await p.waitForTimeout(300); await p.click(".sn-mm .sn-ag"); } else await p.click(".sn-agent");
      await p.waitForSelector("dialog.ar-dlg[open]"); await p.waitForTimeout(450);
      const m = await p.evaluate(() => { const d = document.querySelector(".ar-dlg"), body = d.querySelector(".ar-body"), h2 = d.querySelector("h2"); return { h2: getComputedStyle(h2).fontSize + "/" + getComputedStyle(h2).textAlign, bodyH: body.scrollWidth > body.clientWidth, firstTop: Math.round(d.querySelector(".ar-seg").getBoundingClientRect().top - body.getBoundingClientRect().top) }; });
      console.log(name, w, JSON.stringify(m));
      await p.screenshot({ path: `${OUT}/m-${name}-${w}.png` });
      await ctx.close();
    }
  }
  await b.close();
})();

