const { chromium } = require("D:/Atharva/video-studio/node_modules/playwright");
(async () => {
  const b = await chromium.launch({ channel: "msedge" });
  for (const pg of ["", "doc-test/", "judges/"]) {
    const p = await b.newPage({ viewport: { width: 1440, height: 900 } });
    await p.goto("http://localhost:8791/" + pg, { waitUntil: "load" });
    await p.click(".sn-agent"); await p.waitForSelector("dialog.ar-dlg[open]"); await p.waitForTimeout(400);
    const out = [];
    for (const sel of ["#ar-tr", ".ar-os button[data-os=sh]", ".ar-os button[data-os=ps]", "[data-copy=ar-c1]", ".ar-x", "#ar-cp"]) {
      await p.hover(sel); await p.waitForTimeout(80);
      out.push(sel + "=" + await p.$eval(sel, e => { const s = getComputedStyle(e); return s.backgroundColor + " pad:" + s.padding + " w:" + Math.round(e.getBoundingClientRect().width); }));
    }
    console.log(pg || "home", "\n  " + out.join("\n  "));
    await p.close();
  }
  await b.close();
})();

